const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){e.target.style.opacity='1';e.target.style.transform='translateY(0)';io.unobserve(e.target)}})},{threshold:.1});
document.querySelectorAll('.cl-grid article,.t-row figure,.sc-list article,.pr-grid article,.vi li').forEach((el,i)=>{el.style.opacity='0';el.style.transform='translateY(20px)';el.style.transition=`opacity .7s ease ${i*35}ms,transform .7s ease ${i*35}ms`;io.observe(el)});
